```js
export function createRateLimiter(bytesPerSecond) {
  let tokens = 0; let last = Date.now();
  const waiters = [];
  // simple: allow bursts of up to 1s worth
  function refill() {
    const now = Date.now();
    tokens = Math.min(bytesPerSecond, tokens + (now-last)/1000*bytesPerSecond);
    last = now;
  }
  return {
    async take(n) {
      // n bounded by caller to <= 64KiB
      for(;;){
        refill();
        if (tokens >= n) { tokens -= n; return; }
        const need = n - tokens;
        const ms = Math.ceil(need / bytesPerSecond * 1000);
        await sleep(Math.max(5, ms));
      }
    }
  };
}
```
