// Retrieval engine: durable state, chunked resumable downloads, assembly,
// GHCR publication and round-trip verification.

import { promises as fs, createReadStream } from 'node:fs';
import path from 'node:path';
import { createHash } from 'node:crypto';
import { CONFIG, PATHS, entryTag, checkpointTag } from './config.mjs';
import { httpGetToFile, createRateLimiter, sleep, jitter, TransientError } from './http.mjs';

const STATE_FILE = path.join(PATHS.stateDir, 'files.json');
const PARTIAL_INDEX = path.join(PATHS.partialDir, 'partial-index.json');
const EVIDENCE_DIR = path.join(PATHS.stateDir, 'evidence');

export function sha256File(p) {
  return new Promise((resolve, reject) => {
    const h = createHash('sha256');
    const stream = createReadStream(p);
    stream.on('data', (d) => h.update(d));
    stream.on('end', () => resolve(h.digest('hex')));
    stream.on('error', reject);
  });
}

export function sha256Buf(buf) {
  return createHash('sha256').update(buf).digest('hex');
}

export async function atomicWriteFile(file, data) {
  await fs.mkdir(path.dirname(file), { recursive: true });
  const tmp = `${file}.tmp-${process.pid}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
  await fs.writeFile(tmp, data);
  await fs.rename(tmp, file);
}

export async function atomicWriteJson(file, obj) {
  await atomicWriteFile(file, JSON.stringify(obj, null, 2) + '\n');
}

export async function loadJson(file, fallback) {
  try {
    return JSON.parse(await fs.readFile(file, 'utf8'));
  } catch (err) {
    if (err.code === 'ENOENT') return fallback;
    throw err;
  }
}

// ---------------------------------------------------------------------------
// State
// ---------------------------------------------------------------------------

export async function loadState() {
  const s = await loadJson(STATE_FILE, null);
  if (!s) return { version: 1, files: {}, updatedAt: null };
  return s;
}

let saveChain = Promise.resolve();
export async function saveState(state) {
  state.updatedAt = new Date().toISOString();
  const snapshot = JSON.stringify(state, null, 2) + '\n';
  saveChain = saveChain.then(() => atomicWriteFile(STATE_FILE, snapshot)).catch(() => {});
  return saveChain;
}

export function ensureFileEntry(state, entry) {
  let e = state.files[entry.id];
  if (!e) {
    e = {
      id: entry.id,
      year: entry.year,
      issue: entry.issue,
      format: entry.format,
      filename: entry.filename,
      url: entry.url,
      labelText: entry.labelText,
      labelSize: entry.labelSize,
      expectedBytes: null,
      etag: null,
      lastModified: null,
      chunkSize: CONFIG.chunkSize,
      chunks: {},
      receivedBytes: 0,
      status: 'pending',
      gen: 0,
      attempts: 0,
      retries: 0,
      lastError: null,
      lastErrorAt: null,
      ghcr: null,
      checkpoint: null,
      verified: null,
      updatedAt: new Date().toISOString(),
    };
    state.files[entry.id] = e;
  }
  return e;
}

function chunkName(i) {
  return `chunk-${String(i).padStart(6, '0')}`;
}
export function workspaceDir(id) {
  return path.join(PATHS.stagingDir, id);
}
export function chunksDir(id) {
  return path.join(workspaceDir(id), 'chunks');
}
function chunkPath(id, i) {
  return path.join(chunksDir(id), chunkName(i));
}
export function chunkCount(eff) {
  if (!eff.expectedBytes) return 0;
  if (eff.chunks[0] && eff.chunks[0].bytes >= eff.expectedBytes) return 1;
  return Math.ceil(eff.expectedBytes / eff.chunkSize);
}

// ---------------------------------------------------------------------------
// Manifest / evidence
// ---------------------------------------------------------------------------

export async function loadManifest() {
  return loadJson(path.join(PATHS.stateDir, 'manifest.json'), null);
}
export async function saveManifest(manifest) {
  await atomicWriteJson(path.join(PATHS.stateDir, 'manifest.json'), manifest);
}
export async function saveIndexEvidence(rawBuf, meta) {
  await fs.mkdir(EVIDENCE_DIR, { recursive: true });
  await atomicWriteFile(path.join(EVIDENCE_DIR, 'index.cp1251.html'), rawBuf);
  await atomicWriteJson(path.join(EVIDENCE_DIR, 'index.meta.json'), meta);
}

// ---------------------------------------------------------------------------
// Chunk download with retries
// ---------------------------------------------------------------------------

let lastRequestStart = 0;
async function politeGate() {
  const now = Date.now();
  const at = Math.max(now, lastRequestStart + CONFIG.requestGapMs);
  lastRequestStart = at;
  if (at > now) await sleep(at - now);
}

async function downloadChunkOnce(ctx, entry, eff, chunk, effGen) {
  const start = chunk * eff.chunkSize;
  const end =
    eff.expectedBytes != null ? Math.min(start + eff.chunkSize - 1, eff.expectedBytes - 1) : start + eff.chunkSize - 1;
  const dest = chunkPath(eff.id, chunk);
  const tmp = `${dest}.tmp`;
  await fs.mkdir(path.dirname(dest), { recursive: true });
  const ifRange = eff.etag || eff.lastModified || null;

  await politeGate();
  const meta = await httpGetToFile(eff.url, {
    destTmp: tmp,
    start,
    end,
    ifRange,
    limiter: ctx.limiter,
    idleTimeoutMs: CONFIG.idleTimeoutMs,
    attemptTimeoutMs: CONFIG.attemptTimeoutMs,
  });

  if (effGen !== undefined && eff.gen !== effGen) {
    await fs.rm(tmp, { force: true });
    const err = new Error('file reset during download');
    err.aborted = true;
    throw err;
  }
  if (eff.etag && meta.etag && meta.etag !== eff.etag) {
    await fs.rm(tmp, { force: true });
    const err = new Error('validator (ETag) changed');
    err.validatorChanged = true;
    throw err;
  }

  let total = eff.expectedBytes;
  if (meta.contentRange && meta.contentRange.total != null) total = meta.contentRange.total;
  if (meta.status === 200 && meta.contentLength != null) total = meta.contentLength;
  if (total == null) {
    await fs.rm(tmp, { force: true });
    throw new TransientError('no total size available (server without validators)');
  }

  const expectedThis = meta.status === 200 ? total : Math.min(eff.chunkSize, total - start);
  if (meta.bytesWritten !== expectedThis) {
    await fs.rm(tmp, { force: true });
    throw new TransientError(`short body ${meta.bytesWritten}/${expectedThis}`);
  }
  const hash = await sha256File(tmp);
  await fs.rename(tmp, dest);
  return {
    bytes: meta.bytesWritten,
    sha256: hash,
    total,
    etag: meta.etag || eff.etag,
    lastModified: meta.lastModified || eff.lastModified,
    wholeBody: meta.status === 200,
  };
}

async function withRetries(ctx, eff, chunkIndex, fn) {
  let attempt = 0;
  let backoff = CONFIG.baseBackoffMs;
  for (;;) {
    attempt++;
    eff.attempts++;
    try {
      return await fn(attempt);
    } catch (err) {
      eff.lastError = err.message;
      eff.lastErrorAt = new Date().toISOString();
      if (err.validatorChanged || err.aborted || err.permanent || err.rangeNotSatisfiable) throw err;
      eff.retries++;
      if (attempt >= CONFIG.maxAttemptsPerChunk) throw err;
      let wait = err.retryAfterMs != null ? err.retryAfterMs : backoff;
      wait = Math.max(wait, CONFIG.requestGapMs);
      ctx.log(`retry ${eff.id} chunk ${chunkIndex} #${attempt}: ${err.message} (wait ${Math.round(wait)}ms)`);
      await sleep(jitter(wait));
      backoff = Math.min(CONFIG.maxBackoffMs, backoff * 2);
    }
  }
}

function applyChunkResult(eff, i, info, effGen) {
  if (effGen !== undefined && eff.gen !== effGen) return false;
  eff.chunks[i] = { bytes: info.bytes, sha256: info.sha256 };
  eff.expectedBytes = info.total ?? eff.expectedBytes;
  eff.etag = info.etag || eff.etag;
  eff.lastModified = info.lastModified || eff.lastModified;
  eff.receivedBytes = Object.values(eff.chunks).reduce((a, c) => a + c.bytes, 0);
  eff.cleanupPasses = 0;
  return true;
}

function resetForRetry(eff, reason) {
  eff.chunks = {};
  eff.receivedBytes = 0;
  eff.gen = (eff.gen || 0) + 1;
  if (reason === 'validatorChanged') {
    eff.etag = null;
    eff.lastModified = null;
  }
  eff.status = 'pending';
  eff.lastError = reason;
}

export async function downloadFile(ctx, entry) {
  const { state, pool } = ctx;
  const eff = ensureFileEntry(state, entry);
  if (eff.status === 'published') return { done: true };
  eff.status = 'in_progress';
  const gen = eff.gen;

  // Chunk 0 establishes size (or the whole body when the range is ignored).
  if (eff.expectedBytes == null || !eff.chunks[0]) {
    try {
      const info = await withRetries(ctx, eff, 0, () => downloadChunkOnce(ctx, entry, eff, 0, gen));
      applyChunkResult(eff, 0, info, gen);
      await saveState(state);
    } catch (err) {
      if (err.validatorChanged || err.aborted) resetForRetry(eff, err.validatorChanged ? 'validatorChanged' : 'aborted');
      await saveState(state);
      throw err;
    }
  }

  const n = chunkCount(eff);
  const missing = [];
  for (let i = 0; i < n; i++) {
    if (eff.chunks[i] && (await fileValid(eff.id, i, eff.chunks[i]))) continue;
    missing.push(i);
  }

  const failures = [];
  await Promise.all(
    missing.map((i) =>
      pool.run(async () => {
        const myGen = eff.gen;
        try {
          const info = await withRetries(ctx, eff, i, () => downloadChunkOnce(ctx, entry, eff, i, myGen));
          if (applyChunkResult(eff, i, info, myGen)) await saveState(state);
        } catch (err) {
          failures.push({ i, err });
        }
      }),
    ),
  );

  if (failures.length > 0) {
    const hard = failures.find((f) => f.err.validatorChanged || f.err.aborted);
    if (hard) resetForRetry(eff, hard.err.validatorChanged ? 'validatorChanged' : 'aborted');
    else if (failures.every((f) => f.err.permanent)) eff.status = 'unavailable';
    await saveState(state);
    return { done: false, failures: failures.map((f) => f.err.message) };
  }

  const haveAll = chunkCount(eff) > 0 && (await allChunksValid(eff));
  if (haveAll) {
    eff.receivedBytes = Object.values(eff.chunks).reduce((a, c) => a + c.bytes, 0);
    return { done: true };
  }
  return { done: false };
}

async function allChunksValid(eff) {
  const n = chunkCount(eff);
  for (let i = 0; i < n; i++) {
    if (!eff.chunks[i]) return false;
    if (!(await fileValid(eff.id, i, eff.chunks[i]))) return false;
  }
  return true;
}

async function fileValid(id, i, info) {
  try {
    const st = await fs.stat(chunkPath(id, i));
    if (st.size !== info.bytes) return false;
    return (await sha256File(chunkPath(id, i))) === info.sha256;
  } catch {
    return false;
  }
}

// ---------------------------------------------------------------------------
// Assembly + publication
// ---------------------------------------------------------------------------

export async function assembleHex(eff) {
  const h = createHash('sha256');
  let bytes = 0;
  const n = chunkCount(eff);
  for (let i = 0; i < n; i++) {
    const info = eff.chunks[i];
    if (!info) throw new Error(`missing chunk ${i} for ${eff.id}`);
    const buf = await fs.readFile(chunkPath(eff.id, i));
    if (buf.length !== info.bytes) throw new Error(`chunk ${i} length mismatch for ${eff.id}`);
    h.update(buf);
    bytes += buf.length;
  }
  return { sha256: h.digest('hex'), bytes };
}

export async function assembleToFile(eff, dest) {
  await fs.mkdir(path.dirname(dest), { recursive: true });
  const out = await fs.open(dest, 'w');
  try {
    const n = chunkCount(eff);
    for (let i = 0; i < n; i++) {
      const info = eff.chunks[i];
      if (!info) throw new Error(`missing chunk ${i} for ${eff.id}`);
      const buf = await fs.readFile(chunkPath(eff.id, i));
      if (buf.length !== info.bytes) throw new Error(`chunk ${i} length mismatch for ${eff.id}`);
      await out.write(buf);
    }
  } finally {
    await out.close();
  }
}

export async function publishFile(ctx, entry) {
  const { state, ghcr, log } = ctx;
  const eff = ensureFileEntry(state, entry);
  const tag = entryTag(entry);
  const work = path.join(workspaceDir(eff.id), 'out', `${eff.id}.bin`);

  const { sha256, bytes } = await assembleHex(eff);
  await assembleToFile(eff, work);

  log(`publishing ${eff.id} (${bytes} bytes) as ${tag}`);
  const push = await ghcr.pushFile(tag, work, {
    title: eff.filename,
    annotations: {
      'org.opencontainers.image.title': eff.filename,
      'shurik.nauka.year': String(eff.year),
      'shurik.nauka.issue': eff.issue,
      'shurik.nauka.format': eff.format,
      'shurik.nauka.sha256': sha256,
      'shurik.nauka.source-url': eff.url,
      'shurik.nauka.index-url': ctx.manifest.indexUrl,
    },
  });

  eff.sha256 = sha256;
  eff.expectedBytes = bytes;
  eff.ghcr = { tag, digest: push.digest, title: eff.filename, pushedAt: new Date().toISOString() };
  await saveState(state);

  // Round-trip verification: pull the tag back and compare bytes.
  const verifyDir = path.join(PATHS.stagingDir, 'verify', eff.id);
  await fs.rm(verifyDir, { recursive: true, force: true });
  await ghcr.pull(tag, verifyDir);
  const pulled = path.join(verifyDir, path.basename(work));
  const pulledHash = await sha256File(pulled);
  const ok = pulledHash === sha256;
  eff.verified = { at: new Date().toISOString(), pulledSha256: pulledHash, ok, digest: push.digest };
  await fs.rm(verifyDir, { recursive: true, force: true });
  if (!ok) {
    eff.status = 'in_progress';
    eff.lastError = 'round-trip verification mismatch';
    eff.lastErrorAt = new Date().toISOString();
    await saveState(state);
    throw new Error(`round-trip verification failed for ${eff.id}`);
  }
  eff.status = 'published';
  eff.publishedAt = new Date().toISOString();
  eff.lastError = null;
  await saveState(state);

  await fs.rm(workspaceDir(eff.id), { recursive: true, force: true });
  await clearGitPartial(eff.id);
  await saveState(state);
  log(`verified ${eff.id}: ${sha256}`);
  return { sha256, bytes, digest: push.digest, tag };
}

async function clearGitPartial(id) {
  await fs.rm(path.join(PATHS.partialDir, `${id}.prefix`), { force: true });
}

// ---------------------------------------------------------------------------
// Durable checkpoints
// ---------------------------------------------------------------------------

export async function checkpointPartials(ctx) {
  const { state, ghcr, log } = ctx;
  const inProgress = Object.values(state.files).filter(
    (e) => e.status === 'in_progress' && Object.keys(e.chunks).length > 0,
  );

  // Selected small prefixes on the control branch.
  await fs.mkdir(PATHS.partialDir, { recursive: true });
  const partialIndex = { version: 1, updatedAt: new Date().toISOString(), partials: {} };
  let budget = CONFIG.gitPartialMaxTotalBytes;
  for (const eff of inProgress) {
    if (budget <= 0) break;
    const prefix = await buildContiguousPrefix(eff.id, eff.chunks, eff.chunkSize);
    if (!prefix || prefix.bytes === 0) continue;
    const cap = Math.min(prefix.bytes, CONFIG.gitPartialMaxBytesPerFile, budget);
    const buf = prefix.buffer.subarray(0, cap);
    await atomicWriteFile(path.join(PATHS.partialDir, `${eff.id}.prefix`), buf);
    partialIndex.partials[eff.id] = {
      bytes: buf.length,
      sha256: sha256Buf(buf),
      chunkSize: eff.chunkSize,
      at: new Date().toISOString(),
    };
    budget -= buf.length;
  }
  await atomicWriteJson(PARTIAL_INDEX, partialIndex);

  // Full chunk workspaces to GHCR checkpoint artifacts.
  for (const eff of inProgress) {
    const dir = chunksDir(eff.id);
    let names = [];
    try {
      names = (await fs.readdir(dir)).filter((f) => f.startsWith('chunk-'));
    } catch {
      continue;
    }
    if (names.length === 0) continue;
    for (const f of await fs.readdir(dir)) {
      if (f.endsWith('.tmp')) await fs.rm(path.join(dir, f), { force: true });
    }
    const bytes = (
      await Promise.all(names.map(async (f) => (await fs.stat(path.join(dir, f))).size))
    ).reduce((a, b) => a + b, 0);
    if (eff.checkpoint && eff.checkpoint.bytes === bytes) continue;
    try {
      const res = await ghcr.pushDir(checkpointTag(eff.id), dir);
      eff.checkpoint = { digest: res.digest, bytes, chunks: names.length, at: new Date().toISOString() };
      log(`checkpointed ${eff.id} (${bytes} bytes, ${names.length} chunks) -> ${res.digest}`);
    } catch (err) {
      log(`checkpoint push failed for ${eff.id}: ${err.message}`);
    }
    await saveState(state);
  }
  return partialIndex;
}

async function buildContiguousPrefix(id, chunks, chunkSize) {
  const parts = [];
  let bytes = 0;
  for (let i = 0; ; i++) {
    if (!chunks[i]) break;
    const buf = await fs.readFile(chunkPath(id, i)).catch(() => null);
    if (!buf || buf.length !== chunks[i].bytes) break;
    if (sha256Buf(buf) !== chunks[i].sha256) break;
    parts.push(buf);
    bytes += buf.length;
    if (bytes >= CONFIG.gitPartialMaxBytesPerFile) break;
  }
  if (parts.length === 0) return null;
  return { buffer: Buffer.concat(parts), bytes, chunkCount: parts.length };
}

export async function restoreFromGitPartials(state, log = () => {}) {
  const idx = await loadJson(PARTIAL_INDEX, null);
  if (!idx) return 0;
  let restored = 0;
  for (const [id, info] of Object.entries(idx.partials || {})) {
    const eff = state.files[id];
    if (!eff || eff.status === 'published') continue;
    let buf;
    try {
      buf = await fs.readFile(path.join(PATHS.partialDir, `${id}.prefix`));
    } catch {
      continue;
    }
    if (buf.length !== info.bytes || sha256Buf(buf) !== info.sha256) {
      log(`ignoring torn git partial for ${id}`);
      continue;
    }
    const nChunks = Math.ceil(buf.length / info.chunkSize);
    for (let i = 0; i < nChunks; i++) {
      const start = i * info.chunkSize;
      const chunkBuf = buf.subarray(start, Math.min(start + info.chunkSize, buf.length));
      const ci = eff.chunks[i];
      if (!ci || chunkBuf.length !== ci.bytes || sha256Buf(chunkBuf) !== ci.sha256) continue;
      const dest = chunkPath(id, i);
      try {
        const st = await fs.stat(dest);
        if (st.size === chunkBuf.length && (await sha256File(dest)) === ci.sha256) continue;
      } catch {
        /* missing */
      }
      await atomicWriteFile(dest, chunkBuf);
      restored++;
      log(`restored chunk ${i} of ${id} from git partial`);
    }
  }
  return restored;
}

export async function restoreFromCheckpoints(ctx) {
  const { state, ghcr, log } = ctx;
  let restored = 0;
  for (const eff of Object.values(state.files)) {
    if (eff.status === 'published') continue;
    if (!eff.checkpoint || !eff.checkpoint.digest) continue;
    let missing = false;
    for (const i of Object.keys(eff.chunks)) {
      if (!(await fileValid(eff.id, Number(i), eff.chunks[i]))) {
        missing = true;
        break;
      }
    }
    if (!missing) continue;
    log(`restoring ${eff.id} from GHCR checkpoint ${eff.checkpoint.digest}`);
    try {
      await ghcr.pull(checkpointTag(eff.id), chunksDir(eff.id));
    } catch (err) {
      log(`checkpoint pull failed for ${eff.id}: ${err.message}`);
      continue;
    }
    for (const i of Object.keys(eff.chunks)) {
      if (!(await fileValid(eff.id, Number(i), eff.chunks[i]))) {
        await fs.rm(chunkPath(eff.id, Number(i)), { force: true });
        delete eff.chunks[i];
        restored--;
      } else {
        restored++;
      }
    }
    eff.receivedBytes = Object.values(eff.chunks).reduce((a, c) => a + c.bytes, 0);
    await saveState(state);
  }
  return restored;
}

// ---------------------------------------------------------------------------
// Concurrency pool + ordering + pass runner
// ---------------------------------------------------------------------------

export function createPool(size) {
  let active = 0;
  const queue = [];
  const next = () => {
    if (active >= size || queue.length === 0) return;
    active++;
    const { fn, resolve, reject } = queue.shift();
    Promise.resolve()
      .then(fn)
      .then(resolve, reject)
      .finally(() => {
        active--;
        next();
      });
  };
  return {
    run(fn) {
      return new Promise((resolve, reject) => {
        queue.push({ fn, resolve, reject });
        next();
      });
    },
    get active() {
      return active;
    },
  };
}

export function estimateBytes(labelSize) {
  const m = /(\d+(?:\.\d+)?)\s*M/i.exec(labelSize || '');
  return m ? Math.round(Number(m[1]) * 1024 * 1024) : null;
}

export function orderEntries(entries, state) {
  return [...entries].sort((a, b) => {
    const ea = state.files[a.id];
    const eb = state.files[b.id];
    const pa = ea && ea.status === 'published';
    const pb = eb && eb.status === 'published';
    if (pa !== pb) return pa ? 1 : -1;
    const sa = (ea && ea.expectedBytes) || estimateBytes(a.labelSize) || 1e12;
    const sb = (eb && eb.expectedBytes) || estimateBytes(b.labelSize) || 1e12;
    return sa - sb;
  });
}

export function createContext({ state, manifest, ghcr, log = console.log }) {
  return {
    state,
    manifest,
    ghcr,
    log,
    limiter: createRateLimiter(CONFIG.bandwidthLimitBps),
    pool: createPool(CONFIG.maxConcurrency),
  };
}

export async function runPass(ctx) {
  const { state, manifest, log } = ctx;
  const deadline = Date.now() + CONFIG.passBudgetMs;
  const ordered = orderEntries(manifest.entries, state);
  const results = [];
  for (const entry of ordered) {
    if (Date.now() >= deadline) break;
    const eff = ensureFileEntry(state, entry);
    if (eff.status === 'published' || eff.status === 'unavailable') continue;
    log(`-- file ${eff.id} (${eff.labelSize}) --`);
    try {
      const r = await downloadFile(ctx, entry);
      if (r.done) {
        const pub = await publishFile(ctx, entry);
        results.push({ id: eff.id, status: 'published', ...pub });
      } else {
        results.push({ id: eff.id, status: 'in_progress', received: eff.receivedBytes });
        // If a file cannot progress (repeated failures), move on.
        if ((eff.lastError || '').includes('short body') && eff.retries > 0) continue;
      }
    } catch (err) {
      log(`file ${eff.id} error: ${err.message}`);
      results.push({ id: eff.id, status: eff.status, error: err.message });
      if (err.validatorChanged || err.aborted) resetForRetry(eff, 'validatorChanged');
      await saveState(state);
    }
  }
  await checkpointPartials(ctx);
  await saveState(state);
  return results;
}

export { checkpointTag, entryTag };

#!/usr/bin/env node
// Nauka i Zhizn (1934-39) scan retrieval CLI.
import { promises as fs } from 'node:fs';
import path from 'node:path';
import { createHash } from 'node:crypto';
import {
  CONFIG,
  PATHS,
  REGISTRY,
  INDEX_URL,
  INDEX_TAG,
  CHECKPOINT_TAG,
  ARTIFACT_TYPE,
  SOURCE_REPO,
  entryTag,
  checkpointTag,
} from './config.mjs';
import { decodeIndex, manifestFromHtml, parseIndex } from './parse-index.mjs';
import { httpGetToFile, TransientError, sleep, jitter } from './http.mjs';
import { Ghcr } from './ghcr.mjs';
import {
  loadState,
  saveState,
  ensureFileEntry,
  loadManifest,
  saveManifest,
  saveIndexEvidence,
  createContext,
  runPass,
  restoreFromGitPartials,
  restoreFromCheckpoints,
  publishFile,
  sha256File,
  sha256Buf,
  atomicWriteJson,
  chunkCount,
  workspaceDir,
  chunksDir,
} from './engine.mjs';

const REPO_ROOT = path.resolve(path.dirname(new URL(import.meta.url).pathname), '..', '..');
const STATUS_FILE = path.join(REPO_ROOT, 'NAUKA_STATUS.md');
const TOOLS_MANIFEST = path.join(REPO_ROOT, 'tools/nauka/manifest.json');

function log(...a) {
  console.log(new Date().toISOString(), ...a);
}

// ---------------------------------------------------------------------------
// discover
// ---------------------------------------------------------------------------

async function fetchIndexBytes({ offline } = {}) {
  if (offline) {
    return { bytes: await fs.readFile(offline), source: 'offline', fetchedAt: new Date().toISOString() };
  }
  const tmp = path.join(PATHS.stagingDir, 'index.download.html');
  await fs.mkdir(PATHS.stagingDir, { recursive: true });
  let attempts = 0;
  let backoff = 2000;
  for (;;) {
    attempts++;
    try {
      const meta = await httpGetToFile(INDEX_URL, {
        destTmp: tmp,
        idleTimeoutMs: CONFIG.idleTimeoutMs,
        attemptTimeoutMs: 180000,
      });
      const bytes = await fs.readFile(tmp);
      return { bytes, source: INDEX_URL, fetchedAt: new Date().toISOString(), attempts, meta: { status: meta.status } };
    } catch (err) {
      if (attempts >= CONFIG.maxAttemptsPerChunk) throw err;
      log(`index fetch attempt ${attempts} failed: ${err.message}`);
      await sleep(jitter(backoff));
      backoff = Math.min(CONFIG.maxBackoffMs, backoff * 2);
    }
  }
}

async function cmdDiscover(args) {
  const offline = args.includes('--offline') ? args[args.indexOf('--offline') + 1] : null;
  const fetched = await fetchIndexBytes({ offline });
  const sha256 = sha256Buf(fetched.bytes);
  const html = decodeIndex(fetched.bytes);
  const manifest = manifestFromHtml(html, {
    indexSha256: sha256,
    indexBytes: fetched.bytes.length,
    fetchedAt: fetched.fetchedAt,
    fetchSource: fetched.source,
  });
  await saveManifest(manifest);
  // Keep a compact, auditable copy on the work branch too.
  await fs.mkdir(path.dirname(TOOLS_MANIFEST), { recursive: true });
  await atomicWriteJson(TOOLS_MANIFEST, compactManifest(manifest));
  if (!offline) {
    await saveIndexEvidence(fetched.bytes, {
      url: INDEX_URL,
      fetchedAt: fetched.fetchedAt,
      bytes: fetched.bytes.length,
      sha256,
      encoding: 'windows-1251',
      attempts: fetched.attempts,
    });
  }
  log(`discovered ${manifest.totalFiles} files across years ${manifest.years.join(',')}; index sha256=${sha256}`);
  for (const y of manifest.years) {
    const c = manifest.coverage[y];
    log(`  ${y}: ${c.fileCount} files, issues ${c.issues.join(',')}, missing months ${c.missingMonths.join(',') || 'none'}`);
  }
  return manifest;
}

function compactManifest(manifest) {
  return {
    version: 1,
    indexUrl: manifest.indexUrl,
    indexSha256: manifest.indexSha256,
    indexBytes: manifest.indexBytes,
    fetchedAt: manifest.fetchedAt,
    years: manifest.years,
    totalFiles: manifest.totalFiles,
    entries: manifest.entries.map((e) => ({
      id: e.id,
      year: e.year,
      issue: e.issue,
      format: e.format,
      filename: e.filename,
      url: e.url,
      labelText: e.labelText,
      labelSize: e.labelSize,
    })),
    coverage: manifest.coverage,
  };
}

// ---------------------------------------------------------------------------
// GHCR context
// ---------------------------------------------------------------------------

async function makeGhcr() {
  const ghcr = await Ghcr.create({ log });
  await ghcr.login();
  return ghcr;
}

// Reconcile local state with existing GHCR artifacts so verified uploads are
// never restarted from zero.
async function reconcile(ctx) {
  const { state, manifest, ghcr, log } = ctx;
  for (const entry of manifest.entries) {
    const eff = ensureFileEntry(state, entry);
    if (eff.status === 'published') continue;
    const tag = entryTag(entry);
    try {
      const manifestJson = await ghcr.manifest(tag);
      const ann = manifestJson.annotations || {};
      const layer = (manifestJson.layers || []).find((l) => l.annotations?.['org.opencontainers.image.title']);
      const claimed = ann['shurik.nauka.sha256'];
      if (!claimed) continue;
      const digest = await ghcr.resolve(tag);
      const verifyDir = path.join(PATHS.stagingDir, 'reconcile', eff.id);
      await fs.rm(verifyDir, { recursive: true, force: true });
      await ghcr.pull(tag, verifyDir);
      const files = await fs.readdir(verifyDir);
      const pulled = files.find((f) => f.endsWith('.bin') || f === eff.id) || files[0];
      const hash = await sha256File(path.join(verifyDir, pulled));
      await fs.rm(verifyDir, { recursive: true, force: true });
      if (hash === claimed) {
        eff.status = 'published';
        eff.sha256 = claimed;
        eff.ghcr = { tag, digest, title: eff.filename, pushedAt: ann['org.opencontainers.image.created'] || null };
        eff.verified = { at: new Date().toISOString(), pulledSha256: hash, ok: true, recovered: true };
        log(`reconciled already-published ${eff.id} (${digest})`);
      }
    } catch {
      /* tag absent -> not published yet */
    }
  }
  await saveState(state);
}

// ---------------------------------------------------------------------------
// retrieve
// ---------------------------------------------------------------------------

async function cmdRetrieve(args) {
  let manifest = await loadManifest();
  if (!manifest) {
    log('no manifest; running discover first');
    manifest = await cmdDiscover(['--offline', '']); // will fail; caller should discover explicitly
  }
  const state = await loadState();
  const ghcr = await makeGhcr();
  const ctx = createContext({ state, manifest, ghcr, log });

  await restoreFromGitPartials(state, log);
  await restoreFromCheckpoints(ctx);
  await reconcile(ctx);

  const passes = Number(getFlag(args, '--passes') || 1);
  for (let p = 0; p < passes; p++) {
    log(`=== pass ${p + 1}/${passes} ===`);
    const results = await runPass(ctx);
    log(`pass ${p + 1} results: ${JSON.stringify(results)}`);
    const remaining = remainingCount(state, manifest);
    log(`remaining files: ${remaining}`);
    if (remaining === 0) break;
  }
  await writeStatus(state, manifest, ctx);
}

function getFlag(args, name) {
  const i = args.indexOf(name);
  return i >= 0 ? args[i + 1] : null;
}

function remainingCount(state, manifest) {
  let n = 0;
  for (const e of manifest.entries) {
    const eff = state.files[e.id];
    if (!eff || eff.status !== 'published') n++;
  }
  return n;
}

// ---------------------------------------------------------------------------
// verify / index / status
// ---------------------------------------------------------------------------

async function cmdVerify() {
  const manifest = await loadManifest();
  const state = await loadState();
  const ghcr = await makeGhcr();
  let ok = 0;
  const problems = [];
  for (const entry of manifest.entries) {
    const eff = state.files[entry.id];
    if (!eff || eff.status !== 'published') {
      problems.push(`${entry.id}: not published`);
      continue;
    }
    const tag = entryTag(entry);
    try {
      const digest = await ghcr.resolve(tag);
      const dir = path.join(PATHS.stagingDir, 'verify', entry.id);
      await fs.rm(dir, { recursive: true, force: true });
      await ghcr.pull(tag, dir);
      const files = await fs.readdir(dir);
      const pulled = files.find((f) => f.endsWith('.bin')) || files[0];
      const hash = await sha256File(path.join(dir, pulled));
      await fs.rm(dir, { recursive: true, force: true });
      if (hash !== eff.sha256) problems.push(`${entry.id}: hash mismatch ${hash} != ${eff.sha256}`);
      else if (digest !== eff.ghcr.digest) problems.push(`${entry.id}: digest moved ${digest} != ${eff.ghcr.digest}`);
      else ok++;
    } catch (err) {
      problems.push(`${entry.id}: ${err.message}`);
    }
  }
  log(`verify: ${ok}/${manifest.entries.length} ok; problems: ${problems.length}`);
  for (const p of problems) log(`  PROBLEM ${p}`);
  await writeStatus(state, manifest, { manifest });
  return problems.length === 0;
}

async function cmdIndex() {
  const manifest = await loadManifest();
  const state = await loadState();
  const ghcr = await makeGhcr();
  const files = manifest.entries.map((e) => {
    const eff = state.files[e.id] || {};
    return {
      id: e.id,
      year: e.year,
      issue: e.issue,
      format: e.format,
      filename: e.filename,
      sourceUrl: e.url,
      tag: entryTag(e),
      digest: eff.ghcr ? eff.ghcr.digest : null,
      sha256: eff.sha256 || null,
      bytes: eff.expectedBytes || null,
      status: eff.status || 'pending',
    };
  });
  const published = files.filter((f) => f.status === 'published');
  const indexDoc = {
    version: 1,
    kind: 'shurik-nauka-collection',
    indexUrl: manifest.indexUrl,
    indexSha256: manifest.indexSha256,
    registry: REGISTRY,
    source: SOURCE_REPO,
    generatedAt: new Date().toISOString(),
    totalFiles: files.length,
    publishedFiles: published.length,
    remainingFiles: files.length - published.length,
    coverage: manifest.coverage,
    files,
  };
  const tmpDir = path.join(PATHS.stagingDir, 'index-publish');
  await fs.rm(tmpDir, { recursive: true, force: true });
  await fs.mkdir(tmpDir, { recursive: true });
  const indexFile = path.join(tmpDir, 'nij-1934-39-index.json');
  await fs.writeFile(indexFile, JSON.stringify(indexDoc, null, 2) + '\n');
  const res = await ghcr.pushFile(INDEX_TAG, indexFile, {
    title: 'nij-1934-39-index.json',
    annotations: {
      'org.opencontainers.image.title': 'nij-1934-39-index.json',
      'shurik.nauka.kind': 'collection-index',
      'shurik.nauka.total-files': String(files.length),
      'shurik.nauka.published-files': String(published.length),
      'shurik.nauka.index-url': manifest.indexUrl,
    },
  });
  // Resume/checkpoint marker tag.
  const checkpointFile = path.join(tmpDir, 'nij-1934-39-checkpoint.json');
  await fs.writeFile(
    checkpointFile,
    JSON.stringify(
      {
        version: 1,
        kind: 'shurik-nauka-resume-checkpoint',
        generatedAt: new Date().toISOString(),
        published: published.map((f) => ({ id: f.id, tag: f.tag, digest: f.digest, sha256: f.sha256, bytes: f.bytes })),
        remaining: files.filter((f) => f.status !== 'published').map((f) => ({ id: f.id, status: f.status })),
        indexTag: INDEX_TAG,
      },
      null,
      2,
    ) + '\n',
  );
  const res2 = await ghcr.pushFile(CHECKPOINT_TAG, checkpointFile, {
    title: 'nij-1934-39-checkpoint.json',
    annotations: {
      'org.opencontainers.image.title': 'nij-1934-39-checkpoint.json',
      'shurik.nauka.kind': 'resume-checkpoint',
    },
  });
  log(`published index ${INDEX_TAG} -> ${res.digest}`);
  log(`published checkpoint ${CHECKPOINT_TAG} -> ${res2.digest}`);
  await writeStatus(state, manifest, { manifest });
}

async function cmdStatus() {
  const manifest = await loadManifest();
  const state = await loadState();
  await writeStatus(state, manifest, { manifest });
}

// ---------------------------------------------------------------------------
// status report
// ---------------------------------------------------------------------------

async function writeStatus(state, manifest, ctx) {
  if (!manifest) return;
  const entries = manifest.entries;
  const byYear = new Map();
  const counts = { published: 0, in_progress: 0, pending: 0, unavailable: 0 };
  const verified = [];
  const retryable = [];
  const permanent = [];
  let bytesPublished = 0;
  let bytesTotal = 0;
  for (const e of entries) {
    const eff = state.files[e.id] || { status: 'pending' };
    counts[eff.status] = (counts[eff.status] || 0) + 1;
    if (!byYear.has(e.year)) byYear.set(e.year, { total: 0, published: 0 });
    const y = byYear.get(e.year);
    y.total++;
    if (eff.status === 'published') {
      y.published++;
      bytesPublished += eff.expectedBytes || 0;
      verified.push(`- \`${entryTag(e)}\` @ \`${eff.ghcr?.digest}\` — ${eff.filename} (${eff.expectedBytes || '?'} B, sha256 ${String(eff.sha256).slice(0, 16)}…)`);
    } else if (eff.status === 'unavailable') {
      permanent.push(`- ${e.id}: ${eff.lastError || 'unavailable'}`);
    } else {
      retryable.push(`- ${e.id}: ${eff.status} ${eff.receivedBytes || 0}/${eff.expectedBytes || '?'} B (${eff.lastError || 'no error'})`);
    }
    bytesTotal += eff.expectedBytes || 0;
  }
  const lines = [];
  lines.push('# NAUKA_STATUS — Nauka i Zhizn 1934-39 scan retrieval');
  lines.push('');
  lines.push(`Updated: ${new Date().toISOString()}`);
  lines.push('');
  lines.push('## Index evidence');
  lines.push(`- Index URL: ${manifest.indexUrl}`);
  lines.push(`- Index sha256 (windows-1251 bytes): \`${manifest.indexSha256}\``);
  lines.push(`- Index bytes: ${manifest.indexBytes}`);
  lines.push(`- Discovered scan files: ${entries.length} (years ${manifest.years.join(', ')})`);
  lines.push(`- Manifest (tracked copy): \`tools/nauka/manifest.json\`; raw index preserved at \`data/nauka/state/evidence/index.cp1251.html\``);
  lines.push('');
  lines.push('## Totals');
  lines.push(`- discovered: ${entries.length}`);
  lines.push(`- published (GHCR, round-trip verified): ${counts.published}`);
  lines.push(`- in progress: ${counts.in_progress}`);
  lines.push(`- pending: ${counts.pending}`);
  lines.push(`- unavailable/permanent: ${counts.unavailable}`);
  lines.push(`- remaining: ${entries.length - counts.published}`);
  lines.push(`- bytes published: ${bytesPublished} / ${bytesTotal || 'unknown'}`);
  lines.push('');
  lines.push('## Per year');
  for (const [year, y] of [...byYear.entries()].sort()) {
    const c = manifest.coverage[year];
    lines.push(`- ${year}: ${y.published}/${y.total} published; missing months: ${c.missingMonths.join(',') || 'none'}`);
  }
  lines.push('');
  lines.push('## Registry');
  lines.push(`- Registry: ${REGISTRY}`);
  lines.push(`- Source annotation: ${SOURCE_REPO}`);
  lines.push(`- Artifact type: ${ARTIFACT_TYPE}`);
  lines.push(`- Collection/index tag: ${INDEX_TAG}`);
  lines.push(`- Resume/checkpoint tag: ${CHECKPOINT_TAG}`);
  lines.push(`- Per-file tags: \`nij-<year>-<issue>-<format>\``);
  lines.push('');
  lines.push('## Verified GHCR references');
  lines.push(verified.length ? verified.join('\n') : '- (none yet)');
  lines.push('');
  lines.push('## Retryable / in-progress');
  lines.push(retryable.length ? retryable.join('\n') : '- (none)');
  lines.push('');
  lines.push('## Unavailable (permanent)');
  lines.push(permanent.length ? permanent.join('\n') : '- (none)');
  lines.push('');
  lines.push('## Throttle and retry settings');
  lines.push(`- aggregate bandwidth cap: ${CONFIG.bandwidthLimitBps} B/s`);
  lines.push(`- concurrency: ${CONFIG.maxConcurrency} connections`);
  lines.push(`- chunk size: ${CONFIG.chunkSize} B`);
  lines.push(`- request-start gap: ${CONFIG.requestGapMs} ms`);
  lines.push(`- retries/chunk: ${CONFIG.maxAttemptsPerChunk}; backoff ${CONFIG.baseBackoffMs}-${CONFIG.maxBackoffMs} ms with jitter`);
  lines.push('');
  lines.push('## Commands (list / pull / resume)');
  lines.push('```bash');
  lines.push(`oras repo tags ${REGISTRY} | sort`);
  lines.push(`oras manifest fetch ${REGISTRY}:${INDEX_TAG} | jq .`);
  lines.push(`oras pull ${REGISTRY}:nij-1939-n01-djv -o ./out`);
  lines.push('node tools/nauka/cli.mjs discover');
  lines.push('node tools/nauka/cli.mjs retrieve --passes 4');
  lines.push('node tools/nauka/cli.mjs verify');
  lines.push('node tools/nauka/cli.mjs index');
  lines.push('```');
  lines.push('');
  await fs.writeFile(STATUS_FILE, lines.join('\n') + '\n');
}

// ---------------------------------------------------------------------------

async function main() {
  const [cmd, ...args] = process.argv.slice(2);
  switch (cmd) {
    case 'discover':
      await cmdDiscover(args);
      break;
    case 'retrieve':
      await cmdRetrieve(args);
      break;
    case 'verify':
      await cmdVerify();
      break;
    case 'index':
      await cmdIndex();
      break;
    case 'status':
      await cmdStatus();
      break;
    default:
      console.error('usage: cli.mjs <discover|retrieve|verify|index|status> [args]');
      process.exit(2);
  }
}

main().catch((err) => {
  console.error('FATAL', err && err.stack ? err.stack : err);
  process.exit(1);
});

